input.newString:
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
$$('#choices .choice').forEach((button,index)=>button.addEventListener('click',()=>{
 if(state.chosen||state.ending)return;
 const v=visitors[visitorIndex()],styles=[[-4,7,5],[-7,5,8],[-6,6,6]][index];
 state.shadow=clamp(state.shadow+styles[0]);state.light=clamp(state.light+styles[1]);state.center=clamp(state.center+styles[2]);state.chosen=true;
 state.met=Array.from(new Set([...state.met,visitorIndex()]));
 state.lastChoice=`${v.opts[index][0]}: ${['You let the feeling speak, and noticed the need inside it.','You made room for the part without asking it to disappear.','You saw both your responsibility and your capacity to choose differently.'][index]}`;
 addEntry(`${v.name}: ${v.opts[index][0].toLowerCase()}. A little more of the hidden became speakable.`);render();
}));
const practices={
 journal:{light:5,shadow:-2,center:3,energy:-8,text:'You kept a dream image close instead of explaining it away.'},
 active:{light:3,shadow:-7,center:8,energy:-16,text:'You let an inner figure speak, and listened without mistaking it for the whole of you.'},
 rest:{light:0,shadow:0,center:3,energy:22,text:'You rested in the garden. Not every insight is earned by effort.'},
 ritual:{light:2,shadow:-4,center:6,energy:-10,text:'You gave an inner contradiction a small, tangible form.'}
};
$$('[data-action]').forEach(button=>button.addEventListener('click',()=>{
 if(state.acted||!state.chosen||state.ending)return;let p=practices[button.dataset.action];
 state.light=clamp(state.light+p.light);state.shadow=clamp(state.shadow+p.shadow);state.center=clamp(state.center+p.center);state.energy=clamp(state.energy+p.energy);state.acted=true;state.lastAction=p.text;
 addEntry(p.text);render();showToast(p.text);
}));
$('#endDay').addEventListener('click',()=>{
 if(!state.acted||!state.chosen||state.ending)return;
 if(state.day>=14){state.ending=true;addEntry('Fourteen days have passed. The house is not finished; it is yours to inhabit.');render();return}
 state.energy=clamp(state.energy+8);state.day++;state.acted=false;state.chosen=false;state.lastAction='';state.lastChoice='';render();window.scrollTo({top:0,behavior:'smooth'});
});
function showModal(title,html){$('#modalTitle').textContent=title;$('#modalText').innerHTML=html;$('#modalBackdrop').classList.remove('hidden')}
$('#modalClose').addEventListener('click',()=>$('#modalBackdrop').classList.add('hidden'));
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')$('#modalBackdrop').classList.add('hidden')});
$('#helpBtn').addEventListener('click',()=>showModal('A practice, not a perfect score','<p>For fourteen days, meet one inner figure, choose how to relate to it, and take one small practice. Then close the day. Your choices are not right or wrong; they shape the kind of attention you bring.</p><p><b>Individuation</b> is the ongoing work of becoming more whole—not becoming flawless, and not becoming only your bright, admired parts. The Shadow is not evil; it holds qualities, needs, and possibilities pushed out of view. Integration means relationship and choice, not erasure.</p><p>Watch the inner weather as a reflection, not a grade. Active imagination and reflection can be tiring; rest is a real practice. At the end, you will receive a closing reflection based on how you traveled. Your field notes and progress are saved on this device.</p>'));
$('#journalBtn').addEventListener('click',()=>showModal('Field notes',state.entries.length?state.entries.map(e=>`<p><b>Day ${e.day}.</b> ${escapeHTML(e.text)}</p>`).join(''):'<p>No notes yet. What you notice will gather here, day by day.</p>'));
function endGame(){
 let welcomed=state.met.length, ending=state.center>=65&&welcomed>=7?'The house of many rooms':state.energy<=18?'The patient return':welcomed>=5?'A wider doorway':'The first rooms';
 let text=state.center>=65&&welcomed>=7?'You made space for every visitor, and stayed with complexity rather than choosing a single, spotless self. Wholeness is not a finish line; it is a relationship you can keep tending.':state.energy<=18?'You came to the edge of your attention. The next step is not to push harder, but to return gently—rest is part of the work.':welcomed>=5?'You opened several doors and learned that what was disowned often carried a need, a gift, or a boundary. Some rooms remain quiet for now.': 'You began the work of turning toward what had been kept outside. Individuation unfolds over a lifetime; this was a beginning, not a verdict.';
 showModal(ending,`<p>${text}</p><p><b>${welcomed} of 7 inner figures welcomed · Wholeness ${state.center} · Energy ${state.energy}</b></p><p>Take one image or question with you. The work continues in ordinary life—in choices, relationships, and what you dare to notice.</p><button class="quiet-btn" id="resetGame">Begin again</button>`);
 $('#resetGame').addEventListener('click',()=>{localStorage.removeItem('innerHouseSave');state={...base};$('#modalBackdrop').classList.add('hidden');render()});
}
render();
</script>
</body>
</html>

